using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the fact-check of a message. Can be only used if messageProperties.can_set_fact_check == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetMessageFactCheckAsync(long chatId = default, long messageId = default, FormattedText text = default)
    {

           using var activity =  StartCallActivity("SetMessageFactCheckAsync", typeof(SetMessageFactCheck).FullName ?? "SetMessageFactCheckAsync");

           try
           {
             return client.SetMessageFactCheckAsync(chatId, messageId, text);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
